<script setup>
import ConfirmAction from '../components/ConfirmAction.vue';
import { useConfirmation } from '../composables/useConfirmation.js';
const { confirmation, requestConfirmation, answerConfirmation } = useConfirmation();
import AppIcon from "../components/AppIcon.vue";
import { ref,computed } from 'vue';
import { directory,saveDirectory,deleteArchive,restoreArchive,isAllocationRuleActive } from '../lib/expense-directory';
import { invoiceStore } from '../invoiceStore';
import { paymentStore } from '../lib/payment-store';
import { allocationKind } from '../lib/payment-records';
const emit = defineEmits(['inspect-buyers']);
const archiveKinds={buyers:'购买方公司',projects:'工地',people:'报销人',purposes:'常用用途',tags:'自定义标签',paymentMethods:'付款方式'};
async function removeArchive(value, archiveKind=kind.value){
 if(!await requestConfirmation('删除'+archiveKinds[archiveKind], '删除“'+value+'”？已有票据内容保留，相关归属规则暂停使用。删除后可在下方“已删除档案”中恢复。'))return;
 try{deleteArchive(archiveKind,value);if(archiveKind==='buyers'&&buyer.value===value)buyer.value='';if(archiveKind==='projects'&&project.value===value)project.value='';message.value='已删除，可在“已删除档案”中恢复';}catch(e){message.value='删除失败：'+e.message;}
}
function restore(item){try{restoreArchive(item.kind,item.value);message.value='档案已恢复';}catch(e){message.value='恢复失败：'+e.message;}}
const bySeller=ref(false);
const name=ref(''),kind=ref('buyers'),seller=ref(''),buyer=ref(''),project=ref(''),message=ref('');
function add(){const n=name.value.trim();if(!n)return;try{saveDirectory({...directory,[kind.value]:[...new Set([...directory[kind.value],n])],deletedArchives:directory.deletedArchives.filter(r=>r.kind!==kind.value||r.value!==n)});name.value='';message.value='已保存';}catch(e){message.value=e.message;}}
function rule(){if(!seller.value.trim()||!buyer.value||!project.value){message.value='请选择购买方和工地，并填写厂家';return;}try{saveDirectory({...directory,rules:[...directory.rules.filter(r=>!(r.seller===seller.value.trim()&&r.buyer===buyer.value&&r.project===project.value)),{seller:seller.value.trim(),buyer:buyer.value,project:project.value}]});message.value='对应关系已保存';}catch(e){message.value=e.message;}}
function removeRule(i){try{saveDirectory({...directory,rules:directory.rules.filter((_,n)=>n!==i)});}catch(e){message.value=e.message;}}
const summary=computed(()=>{const map=new Map();for(const e of [...Object.values(invoiceStore.ledger),...paymentStore.rows.filter(r=>r.evidenceConfirmed&&!r.duplicateOf)]){const kind=allocationKind(e),b=e.buyer||'未归属公司',p=kind==='指定工地'?e.project:kind;const seller=bySeller.value?(e.seller||"未知厂家"):"全部厂家";const k=JSON.stringify([b,p,seller]);const r=map.get(k)||{buyer:b,project:p,seller,total:0,reimbursed:0,count:0};r.total+=Number(e.total)||0;if(e.reimbursement==='已报销')r.reimbursed+=Number(e.total)||0;r.count++;map.set(k,r);}return [...map.values()];});
</script><template>
<section class="expense-screen">
  <ConfirmAction :request="confirmation" @answer="answerConfirmation" />
  <header class="expense-heading"><div><div class="eyebrow">基础档案</div><h1>基础档案</h1></div><span class="soft-badge"><AppIcon name="building" :size="16" /> {{ directory.buyers.length }} 家公司 · {{ directory.projects.length }} 个工地</span></header>
  <div class="directory-layout">
    <section class="finance-card"><header class="finance-card-heading"><AppIcon name="plus" /><div><h2>新增档案</h2></div></header><div class="finance-card-body"><div class="form-grid"><label>档案类型<select v-model="kind"><option v-for="(label,key) in archiveKinds" :key="key" :value="key">{{ label }}</option></select></label><label>档案名称<input v-model="name" :placeholder="'输入'+archiveKinds[kind]+'名称'" @keyup.enter="add" /></label></div><button class="btn-primary" @click="add"><AppIcon name="plus" :size="16" />新增{{ archiveKinds[kind] }}</button><div v-if="!['buyers','projects'].includes(kind)" class="catalog-section"><h3>{{ archiveKinds[kind] }} <span>{{ directory[kind].length }}</span></h3><div class="catalog-tags"><span v-for="value in directory[kind]" :key="value">{{ value }} <button type="button" class="text-action" :aria-label="'移除档案 '+value" @click="removeArchive(value)">×</button></span><p v-if="!directory[kind].length" class="quiet-empty">暂无配置</p></div></div><div class="catalog-section"><button class="btn" :disabled="!directory.buyers.length" @click="emit('inspect-buyers')">一键排查台账购买方</button><p class="field-hint">查看购买方未填写或不在已建公司档案中的发票。</p><h3>购买方 <span>{{ directory.buyers.length }}</span></h3><div class="catalog-tags"><span v-for="b in directory.buyers" :key="b">{{ b }} <button type="button" class="text-action" :aria-label="'删除购买方 '+b" @click="removeArchive(b,'buyers')">删除</button></span><p v-if="!directory.buyers.length" class="quiet-empty">暂无公司档案</p></div></div><div class="catalog-section"><h3>工地 <span>{{ directory.projects.length }}</span></h3><div class="catalog-tags"><span v-for="p in directory.projects" :key="p">{{ p }} <button type="button" class="text-action" :aria-label="'删除工地 '+p" @click="removeArchive(p,'projects')">删除</button></span><p v-if="!directory.projects.length" class="quiet-empty">暂无工地档案</p></div></div></div></section>
    <section class="finance-card"><header class="finance-card-heading"><AppIcon name="link" /><div><h2>厂家与费用归属</h2></div></header><div class="finance-card-body"><p class="field-hint">记录某个厂家对应的购买方和工地，编辑票据时可一键采用；有多条匹配时需人工选择。购买方是否属于本公司，请使用购买方档案排查。</p><label>厂家 / 销售方<input v-model="seller" placeholder="输入厂家全称，与发票销售方一致" /></label><div class="form-grid"><label>购买方<select v-model="buyer"><option value="">选择公司</option><option v-for="b in directory.buyers" :key="b">{{ b }}</option></select></label><label>工地<select v-model="project"><option value="">选择工地</option><option v-for="p in directory.projects" :key="p">{{ p }}</option></select></label></div><button class="btn" @click="rule"><AppIcon name="link" :size="16" />保存对应关系</button><div class="mapping-list"><div v-for="(r,i) in directory.rules" :key="i" class="mapping-item"><div><strong>{{ r.seller }}</strong><small>{{ r.buyer }} / {{ r.project }}</small><small v-if="!isAllocationRuleActive(r)">已停用：购买方或工地已删除，恢复档案后重新启用</small></div><button class="text-action" @click="removeRule(i)">移除</button></div><div v-if="!directory.rules.length" class="quiet-empty">暂无对应关系</div></div></div></section>
  </div>
  <details class="finance-card" v-if="directory.deletedArchives.length"><summary class="finance-card-heading">已删除档案（{{ directory.deletedArchives.length }}）</summary><div class="finance-card-body"><div v-for="item in directory.deletedArchives" :key="item.kind+':'+item.value" class="mapping-item"><span>{{ archiveKinds[item.kind] }} · {{ item.value }}</span><button class="btn" @click="restore(item)">恢复档案</button></div></div></details>
  <p v-if="message" role="status" class="finance-notice">{{ message }}</p>
  <section class="finance-card"><header class="finance-card-heading spread"><div><h2>费用汇总</h2></div><label class="inline-check"><input type="checkbox" v-model="bySeller" />按厂家细分</label></header><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>公司</th><th>工地 / 费用归属</th><th>厂家</th><th class="number-cell">笔数</th><th class="number-cell">采购 / 费用金额</th><th class="number-cell">已报销金额</th></tr></thead><tbody><tr v-for="r in summary" :key="JSON.stringify([r.buyer,r.project,r.seller])"><td>{{ r.buyer }}</td><td>{{ r.project }}</td><td>{{ r.seller }}</td><td class="number-cell">{{ r.count }}</td><td class="number-cell">¥ {{ r.total.toFixed(2) }}</td><td class="number-cell">¥ {{ r.reimbursed.toFixed(2) }}</td></tr><tr v-if="!summary.length"><td colspan="6"><div class="finance-empty"><AppIcon name="chart" :size="32" /><strong>暂无费用记录</strong><span>导入历史发票或核对付款凭证后，这里会显示汇总。</span></div></td></tr></tbody></table></div></section>
</section></template>
